// The window remembers where you drop it.
// doc.js and blocks.js are copies of Kanso's (kanso-panel); edit those.
import { View, div, svg } from "gpui-kit";
import { v_flex, h_flex } from "gpui-base";
import { appHome, exec, watchFolder, focused, props, closeOverlay, theme, home } from "herdr";
import { MarkdownDoc, tildePath } from "./doc.js";

const ICONS = "mods/markdown-panel/icons";
const isMarkdown = (path) => /\.(md|markdown|mdx)$/i.test(path);
const folderOf = (path) => path.replace(/[\\/][^\\/]*$/, "") || "/";
const nameOf = (path) => path.split(/[\\/]/).pop();

// Reads and removes the paths waiting in the inbox; returns the newest.
export async function takeOpens(dir) {
  const r = await exec("sh", ["-c", 'for f in "$1"/*.path; do [ -f "$f" ] || continue; cat "$f"; printf "\\0"; rm -f "$f"; done', "sh", dir]);
  const paths = (r.stdout ?? "").split("\0").map((p) => p.trim()).filter((p) => p.startsWith("/"));
  return paths.pop() ?? null;
}

// Markdown files under a folder, nearest first: what git tracks, else a
// shallow look (no node_modules), at most 40.
export function markdownIn(listing) {
  return listing.split("\n").map((l) => l.trim()).filter((l) => /\.(md|markdown|mdx)$/i.test(l))
    .sort((a, b) => a.split("/").length - b.split("/").length || a.localeCompare(b)).slice(0, 40);
}

export default class MarkdownPanel extends View {
  init(_props, cx) {
    this.doc = null; this.files = null;
    this.folder = focused()?.cwd || home();
    this.handle = cx.focus_handle();
    this.watchOpens(cx);
    this.list(cx);
  }

  list(cx) {
    const folder = this.folder;
    cx.spawn(async (cx) => {
      const git = await exec("git", ["ls-files", "--", "*.md", "*.markdown", "*.mdx"], { cwd: folder }).catch(() => null);
      const out = git?.code === 0 && git.stdout.trim() ? git.stdout
        : (await exec("find", [".", "-maxdepth", "3", "-name", "node_modules", "-prune", "-o", "-type", "f", "(", "-iname", "*.md", "-o", "-iname", "*.mdx", ")", "-print"], { cwd: folder }).catch(() => null))?.stdout ?? "";
      this.files = markdownIn(out.replace(/^\.\//gm, ""));
      cx.notify();
    });
  }

  watchOpens(cx) {
    const dir = `${appHome()}/data/kanso-open`;
    cx.spawn(async (cx) => {
      try {
        await exec("mkdir", ["-p", dir]);
        for (;;) {
          const path = await takeOpens(dir);
          if (path && isMarkdown(path)) this.open(path, cx);
          await watchFolder(dir);
        }
      } catch { /* no inbox: nothing opens from outside */ }
    });
  }

  // Saves what you typed in the file shown before, then shows this one.
  open(path, cx) {
    const before = this.doc;
    cx.spawn(async (cx) => {
      if (before && !(await before.flush())) { cx.notify(); return; }
      before?.release();
      this.doc = new MarkdownDoc(path, null, (to) => { if (isMarkdown(to)) this.open(to, cx); }, ICONS);
      this.doc.load(cx);
      this.watch(path, cx);
      cx.notify();
    });
  }

  // The file is read again on every change in its folder, while it is shown.
  watch(path, cx) {
    const dir = folderOf(path);
    cx.spawn(async (cx) => {
      try { while (this.doc?.path === path) { await watchFolder(dir); if (this.doc?.path === path) this.doc.load(cx); } } catch {}
    });
  }

  close(cx) {
    const doc = this.doc, id = props()?.overlay;
    const done = () => { if (id) closeOverlay(id); };
    if (!doc) { done(); return; }
    cx.spawn(async (cx) => {
      if (!(await doc.flush())) { cx.notify(); return; }
      doc.release(); this.doc = null;
      done();
    });
  }

  // Back to the list of this folder's Markdown files.
  back(cx) {
    const doc = this.doc;
    if (!doc) return;
    cx.spawn(async (cx) => {
      if (!(await doc.flush())) { cx.notify(); return; }
      doc.release(); this.doc = null;
      cx.notify();
    });
  }

  render() {
    const t = theme();
    const doc = this.doc;
    const button = (id, icon, tip, action) => div().id(id).p(4).rounded(6).cursor_pointer().text_color(t.muted).tooltip(tip)
      .hover((s) => s.bg(t.hover).text_color(t.foreground)).on_click((_e, cx) => action(cx))
      .child(svg(`${ICONS}/${icon}.svg`).size(14));
    return v_flex().id("markdown-panel").track_focus(this.handle).size_full().min_h(0).bg(t.background).text_color(t.foreground).text_size(13)
      .on_key_down((e, cx) => doc?.key(e, cx))
      .child(h_flex().h(42).flex_none().px(10).gap(6).items_center().border_b(1).border_color(t.border)
        .when(Boolean(doc), (el) => el.child(button("md-back", "chevron-left", "Markdown in this folder", (cx) => this.back(cx))))
        .child(v_flex().flex_1().min_w(0).pl(doc ? 0 : 4)
          .child(div().truncate().font_semibold().child(doc ? nameOf(doc.path) : "Markdown"))
          .child(div().truncate().text_size(11).text_color(t.dim).child(tildePath(doc ? folderOf(doc.path) : this.folder, null))))
        .children(doc ? doc.controls(t, "md") : [])
        .when(Boolean(doc) && !doc.editing, (el) => el.child(button("md-refresh", "refresh", "Read again", (cx) => doc.load(cx))))
        .child(button("md-close", "close", "Close", (cx) => this.close(cx))))
      .child(doc ? doc.body(t, "md-doc") : this.listView(t));
  }

  listView(t) {
    const files = this.files;
    if (files === null) return div().p(16).text_size(12.5).text_color(t.dim).child("Looking for Markdown…");
    if (!files.length) return div().p(16).text_size(12.5).text_color(t.dim).child("No Markdown files in this folder. Cmd-click a .md path in a terminal to read it here.");
    return div().id("md-files").flex_1().min_h(0).overflow_y_scrollbar().p(6)
      .children(files.map((f, i) => h_flex().id(`md-file-${i}`).h(30).px(10).gap(8).items_center().rounded(6).cursor_pointer()
        .hover((s) => s.bg(t.hover)).on_click((_e, cx) => this.open(`${this.folder}/${f}`, cx))
        .child(div().flex_none().truncate().child(nameOf(f)))
        .child(div().flex_1().min_w(0).truncate().text_size(11.5).text_color(t.dim).child(f.includes("/") ? folderOf(f) : ""))));
  }
}

import { View, div } from "gpui-kit";
import { run, props, closeOverlay, theme } from "herdr";

const actions = {
  "\\": ["pane.split", { direction: "right" }],
  backslash: ["pane.split", { direction: "right" }],
  "-": ["pane.split", { direction: "down" }],
  minus: ["pane.split", { direction: "down" }],
  h: ["pane.go", { direction: "left" }],
  j: ["pane.go", { direction: "down" }],
  k: ["pane.go", { direction: "up" }],
  l: ["pane.go", { direction: "right" }],
  z: ["pane.zoom", {}],
  x: ["pane.close", {}],
  c: ["tab.new", {}],
  b: ["layout.toggle", { id: "sidebar" }],
};

export default class Prefix extends View {
  init(_props, cx) {
    this.handle = cx.focus_handle();
    this.handle.focus();
  }

  key(event, cx) {
    cx.stop_propagation();
    const mods = event.modifiers ?? {};
    const action = !Object.values(mods).some(Boolean) && actions[event.key];
    // ponytail: one-shot prefix panel, no timeout; Escape or an unknown key cancels.
    closeOverlay(props().overlay);
    if (action) run(...action);
  }

  render() {
    const t = theme();
    return div().id("prefix").track_focus(this.handle)
      .on_key_down((event, cx) => this.key(event, cx))
      .size_full().p(16).rounded(8).bg(t.popover).text_color(t.foreground).text_size(13)
      .child("Ctrl+B → \\ right · - below · hjkl focus · z zoom · x close · c new tab · b sidebar · Esc cancel");
  }
}

import { View, div } from "gpui-kit";
import { v_flex, InputState, Input } from "gpui-base";
import { exec, home, spaces, run, theme, props, closeOverlay } from "herdr";

export default class Sessionizer extends View {
  init(_props, cx) {
    this.dirs = [];
    this.filter = "";
    this.at = 0;
    this.message = "Loading projects…";
    this.handle = cx.focus_handle();
    this.input = InputState.new({ placeholder: "Find a project directory…" });
    this.input.on("change", (_e, cx) => {
      this.filter = this.input.value();
      this.at = 0;
      cx.notify();
    });
    this.input.on("submit", () => this.open(this.rows()[this.at]));
    this.input.focus();
    cx.spawn(async (cx) => {
      try {
        const result = await exec("find", [home(), `${home()}/projects`, "-mindepth", "1", "-maxdepth", "1", "-type", "d", "-print0"]);
        if (result.code !== 0) throw new Error(result.stderr);
        this.dirs = [...new Set(result.stdout.split("\0").filter(Boolean))].sort();
        this.message = "No matching directories";
      } catch (error) {
        this.message = `Could not list projects: ${error.message}`;
      }
      cx.notify();
    });
  }

  rows() {
    const needle = this.filter.toLowerCase();
    return this.dirs.filter((dir) => {
      let at = 0;
      for (const char of dir.toLowerCase()) {
        if (char === needle[at]) at++;
      }
      return at === needle.length;
    });
  }

  open(dir) {
    if (!dir) return;
    // ponytail: match the space's current folder; no separate project registry.
    const existing = spaces().find((space) => !space.machine && space.folder.replace(/\/+$/, "") === dir);
    if (existing) run("space.select", { id: existing.id });
    else run("space.new", { name: dir.split("/").pop(), folder: dir });
    closeOverlay(props().overlay);
  }

  render() {
    const t = theme();
    const rows = this.rows();
    const start = Math.max(0, this.at - 7);
    return v_flex().id("sessionizer").track_focus(this.handle)
      .on_key_down((event, cx) => {
        if (event.key === "escape") closeOverlay(props().overlay);
        else if (event.key === "down" && rows.length) this.at = (this.at + 1) % rows.length;
        else if (event.key === "up" && rows.length) this.at = (this.at + rows.length - 1) % rows.length;
        else return;
        cx.stop_propagation();
        cx.notify();
      })
      .w_full().p(16).gap(8).bg(t.popover).text_color(t.foreground)
      .child(div().text_size(15).child("Open project · ↑/↓ select · Enter open · Esc cancel"))
      .child(Input.new(this.input).h(36).px(10).rounded(8).bg(t.background).text_size(13))
      .children(rows.slice(start, start + 8).map((dir, index) => div()
        .id(`project-${start + index}`).px(10).py(7).rounded(6).text_size(13)
        .bg(start + index === this.at ? t.selected : t.popover)
        .cursor_pointer().hover((style) => style.bg(t.hover))
        .on_click(() => this.open(dir))
        .child(dir.startsWith(`${home()}/`) ? `~/${dir.slice(home().length + 1)}` : dir)))
      .when(!rows.length, (element) => element.child(div().text_size(13).child(this.message)));
  }
}

import { View, div } from "gpui-kit";
import { focused, panes, terminals, exec, run, nextCommand, notify, shared, setShared, spaces } from "herdr";

/** @type {Record<string, string>} */
const keys = { left: "h", down: "j", up: "k", right: "l" };

export default class SmartNav extends View {
  /** @param {unknown} _props @param {import("gpui-kit").Context} cx */
  init(_props, cx) {
    if (shared("frame.welcomed") !== "finished") setShared("frame.welcomed", "finished");
    cx.spawn(async () => {
      for (;;) {
        const command = await nextCommand();
        try {
          await this.navigate(command);
        } catch (error) {
          notify({ title: "Smart navigation failed", body: error instanceof Error ? error.message : String(error), level: "error" });
        }
      }
    });
  }

  /** @param {string} command */
  async navigate(command) {
    const focus = focused();
    if (!focus?.pane || !focus.terminal) return;
    const handoff = command.startsWith("move-");
    const direction = handoff ? command.slice(5) : command;
    if (!Object.hasOwn(keys, direction)) return;
    const pane = panes().find((p) => p.pane === focus.pane);
    if (!handoff && pane?.program?.key === "nvim" && !focus.terminal.includes("/")) {
      const labels = terminals().find((t) => t.address === focus.terminal)?.labels;
      const server = labels?.["herdr.nvim-server"];
      const executable = labels?.["herdr.nvim-bin"];
      if (!server || !executable) throw new Error("Restart Neovim to register its RPC server and executable");
      // RPC bypasses hc keys' human-typing quiet period and Desktop's keybindings.
      const result = await exec(executable, ["--server", server, "--remote-send", `<C-${keys[direction]}>`]);
      if (result.code !== 0) throw new Error(result.stderr);
    } else if (pane?.zoomed) {
      // ponytail: CLI round-trips use fresh focus and let the unzoomed geometry render.
      /** @param {...string} args */
      const invoke = async (...args) => {
        const result = await exec("herdr-app", ["do", ...args]);
        if (result.code !== 0) throw new Error(result.stderr);
      };
      await invoke("pane.zoom", "--pane", focus.pane);
      try {
        await invoke("pane.go", "--direction", direction);
      } finally {
        await invoke("pane.zoom");
      }
    } else {
      run("pane.go", { direction });
    }
  }

  render() {
    const colors = { .../** @type {Record<string, string>} */ (shared("space.colors") ?? {}) };
    const palette = ["ansi6", "ansi3", "ansi4", "ansi5", "ansi2", "ansi1"];
    let changed = false;
    for (const space of spaces()) {
      if (colors[space.id] || space.name === "~") continue;
      /** @param {string} color */
      const uses = (color) => Object.values(colors).filter((value) => value === color).length;
      colors[space.id] = palette.reduce((best, color) => uses(color) < uses(best) ? color : best);
      changed = true;
    }
    if (changed) setShared("space.colors", colors);
    // ponytail: main-smart-nav keeps this listener in a visible 1px layout block.
    return div().h(1);
  }
}
